   226  /**
   227   * Internal algorithm for the safe but slow version of gridDiskDistances
   228   *
   229   * Adds the origin cell to the output set (treating it as a hash set)
   230   * and recurses to its neighbors, if needed.
   231   *
   232   * @param  origin      Origin cell
   233   * @param  k           Maximum distance to move from the origin
   234   * @param  out         Array treated as a hash set, elements being either
   235   *                     H3Index or 0.
   236   * @param  distances   Scratch area, with elements paralleling the out array.
   237   *                     Elements indicate ijk distance from the origin cell to
   238   *                     the output cell
   239   * @param  maxIdx      Size of out and scratch arrays (must be
   240   * maxGridDiskSize(k))
   241   * @param  curK        Current distance from the origin
   242   */
   243  void _gridDiskDistancesInternal(H3Index origin, int k, H3Index *out,
   244                                  int *distances, int maxIdx, int curK) {
   245      if (origin == 0) return;
   246
   247      // Put origin in the output array. out is used as a hash set.
   248      int off = origin % maxIdx;
   249      while (out[off] != 0 && out[off] != origin) {
   250          off = (off + 1) % maxIdx;
   251      }
   252
   253      // We either got a free slot in the hash set or hit a duplicate
   254      // We might need to process the duplicate anyways because we got
   255      // here on a longer path before.
   256      if (out[off] == origin && distances[off] <= curK) return;
   257
   258      out[off] = origin;
   259      distances[off] = curK;
   260
   261      // Base case: reached an index k away from the origin.
   262      if (curK >= k) return;
   263
   264      // Recurse to all neighbors in no particular order.
   265      for (int i = 0; i < 6; i++) {
   266          int rotations = 0;
   267          _gridDiskDistancesInternal(
   268              h3NeighborRotations(origin, DIRECTIONS[i], &rotations), k, out,
   269              distances, maxIdx, curK + 1);
   270      }
   271  }
