   293  /**
   294   * Returns the hexagon index neighboring the origin, in the direction dir.
   295   *
   296   * Implementation note: The only reachable case where this returns 0 is if the
   297   * origin is a pentagon and the translation is in the k direction. Thus,
   298   * 0 can only be returned if origin is a pentagon.
   299   *
   300   * @param origin Origin index
   301   * @param dir Direction to move in
   302   * @param rotations Number of ccw rotations to perform to reorient the
   303   *                  translation vector. Will be modified to the new number of
   304   *                  rotations to perform (such as when crossing a face edge.)
   305   * @return H3Index of the specified neighbor or H3_NULL if deleted k-subsequence
   306   *         distortion is encountered.
   307   */
   308  H3Index h3NeighborRotations(H3Index origin, Direction dir, int *rotations) {
   309      H3Index out = origin;
   310
   311      for (int i = 0; i < *rotations; i++) {
   312          dir = _rotate60ccw(dir);
   313      }
   314
   315      int newRotations = 0;
   316      int oldBaseCell = H3_GET_BASE_CELL(out);
   317      if (oldBaseCell < 0 ||
   318          oldBaseCell >= NUM_BASE_CELLS) {  // LCOV_EXCL_BR_LINE
   319          // Base cells less than zero can not be represented in an index
   320          return H3_NULL;
   321      }
   322      Direction oldLeadingDigit = _h3LeadingNonZeroDigit(out);
   323
   324      // Adjust the indexing digits and, if needed, the base cell.
   325      int r = H3_GET_RESOLUTION(out) - 1;
   326      while (true) {
   327          if (r == -1) {
   328              H3_SET_BASE_CELL(out, baseCellNeighbors[oldBaseCell][dir]);
   329              newRotations = baseCellNeighbor60CCWRots[oldBaseCell][dir];
   330
   331              if (H3_GET_BASE_CELL(out) == INVALID_BASE_CELL) {
   332                  // Adjust for the deleted k vertex at the base cell level.
   333                  // This edge actually borders a different neighbor.
   334                  H3_SET_BASE_CELL(out,
   335                                   baseCellNeighbors[oldBaseCell][IK_AXES_DIGIT]);
   336                  newRotations =
   337                      baseCellNeighbor60CCWRots[oldBaseCell][IK_AXES_DIGIT];
   338
   339                  // perform the adjustment for the k-subsequence we're skipping
   340                  // over.
   341                  out = _h3Rotate60ccw(out);
   342                  *rotations = *rotations + 1;
   343              }
   344
   345              break;
   346          } else {
   347              Direction oldDigit = H3_GET_INDEX_DIGIT(out, r + 1);
   348              Direction nextDir;
   349              if (isResolutionClassIII(r + 1)) {
   350                  H3_SET_INDEX_DIGIT(out, r + 1, NEW_DIGIT_II[oldDigit][dir]);
   351                  nextDir = NEW_ADJUSTMENT_II[oldDigit][dir];
   352              } else {
   353                  H3_SET_INDEX_DIGIT(out, r + 1, NEW_DIGIT_III[oldDigit][dir]);
   354                  nextDir = NEW_ADJUSTMENT_III[oldDigit][dir];
   355              }
   356
   357              if (nextDir != CENTER_DIGIT) {
   358                  dir = nextDir;
   359                  r--;
   360              } else {
   361                  // No more adjustment to perform
   362                  break;
   363              }
   364          }
   365      }
   366
   367      int newBaseCell = H3_GET_BASE_CELL(out);
   368      if (_isBaseCellPentagon(newBaseCell)) {
   369          int alreadyAdjustedKSubsequence = 0;
   370
   371          // force rotation out of missing k-axes sub-sequence
   372          if (_h3LeadingNonZeroDigit(out) == K_AXES_DIGIT) {
   373              if (oldBaseCell != newBaseCell) {
   374                  // in this case, we traversed into the deleted
   375                  // k subsequence of a pentagon base cell.
   376                  // We need to rotate out of that case depending
   377                  // on how we got here.
   378                  // check for a cw/ccw offset face; default is ccw
   379
   380                  if (_baseCellIsCwOffset(
   381                          newBaseCell, baseCellData[oldBaseCell].homeFijk.face)) {
   382                      out = _h3Rotate60cw(out);
   383                  } else {
   384                      // See cwOffsetPent in testGridDisk.c for why this is
   385                      // unreachable.
   386                      out = _h3Rotate60ccw(out);  // LCOV_EXCL_LINE
   387                  }
   388                  alreadyAdjustedKSubsequence = 1;
   389              } else {
   390                  // In this case, we traversed into the deleted
   391                  // k subsequence from within the same pentagon
   392                  // base cell.
   393                  if (oldLeadingDigit == CENTER_DIGIT) {
   394                      // Undefined: the k direction is deleted from here
   395                      return H3_NULL;
   396                  } else if (oldLeadingDigit == JK_AXES_DIGIT) {
   397                      // Rotate out of the deleted k subsequence
   398                      // We also need an additional change to the direction we're
   399                      // moving in
   400                      out = _h3Rotate60ccw(out);
   401                      *rotations = *rotations + 1;
   402                  } else if (oldLeadingDigit == IK_AXES_DIGIT) {
   403                      // Rotate out of the deleted k subsequence
   404                      // We also need an additional change to the direction we're
   405                      // moving in
   406                      out = _h3Rotate60cw(out);
   407                      *rotations = *rotations + 5;
   408                  } else {
   409                      // Should never occur
   410                      return H3_NULL;  // LCOV_EXCL_LINE
   411                  }
   412              }
   413          }
   414
   415          for (int i = 0; i < newRotations; i++) out = _h3RotatePent60ccw(out);
   416
   417          // Account for differing orientation of the base cells (this edge
   418          // might not follow properties of some other edges.)
   419          if (oldBaseCell != newBaseCell) {
   420              if (_isBaseCellPolarPentagon(newBaseCell)) {
   421                  // 'polar' base cells behave differently because they have all
   422                  // i neighbors.
   423                  if (oldBaseCell != 118 && oldBaseCell != 8 &&
   424                      _h3LeadingNonZeroDigit(out) != JK_AXES_DIGIT) {
   425                      *rotations = *rotations + 1;
   426                  }
   427              } else if (_h3LeadingNonZeroDigit(out) == IK_AXES_DIGIT &&
   428                         !alreadyAdjustedKSubsequence) {
   429                  // account for distortion introduced to the 5 neighbor by the
   430                  // deleted k subsequence.
   430                  // deleted k subsequence.
   431                  *rotations = *rotations + 1;
   432              }
   433          }
   434      } else {
   435          for (int i = 0; i < newRotations; i++) out = _h3Rotate60ccw(out);
   436      }
   437
   438      *rotations = (*rotations + newRotations) % 6;
   439
   440      return out;
   441  }
