   443  /**
   444   * Get the direction from the origin to a given neighbor. This is effectively
   445   * the reverse operation for h3NeighborRotations. Returns INVALID_DIGIT if the
   446   * cells are not neighbors.
   447   *
   448   * TODO: This is currently a brute-force algorithm, but as it's O(6) that's
   449   * probably acceptable.
   450   */
   451  Direction directionForNeighbor(H3Index origin, H3Index destination) {
   452      bool isPent = H3_EXPORT(isPentagon)(origin);
   453      // Checks each neighbor, in order, to determine which direction the
   454      // destination neighbor is located. Skips CENTER_DIGIT since that
   455      // would be the origin; skips deleted K direction for pentagons.
   456      H3Index neighbor;
   457      for (Direction direction = isPent ? J_AXES_DIGIT : K_AXES_DIGIT;
   458           direction < NUM_DIGITS; direction++) {
   459          int rotations = 0;
   460          neighbor = h3NeighborRotations(origin, direction, &rotations);
   461          if (neighbor == destination) {
   462              return direction;
   463          }
   464      }
   465      return INVALID_DIGIT;
   466  }
