   362  /**
   363   * Rotates ijk coordinates 60 degrees counter-clockwise. Works in place.
   364   *
   365   * @param ijk The ijk coordinates.
   366   */
   367  void _ijkRotate60ccw(CoordIJK *ijk) {
   368      // unit vector rotations
   369      CoordIJK iVec = {1, 1, 0};
   370      CoordIJK jVec = {0, 1, 1};
